// Stealth detection data types - stance, detection tuning, watchman doze tuning and the
// per-target sighting record (design doc §2.4 "Stealth - the quiet half of the raid": a guard's
// sighting must hold ~1.5s to confirm, crouch and cover tighten effective detection range).
// 2026-08-04 (Block D): first stealth types in the module - nothing detection-side existed
// before, so every number here is tuning-owned and lives on the observer component.
#pragma once

#include "CoreMinimal.h"
#include "GSStealthTypes.generated.h"

/**
 * How a would-be-seen actor is carrying itself. Crouch is the Scout's stealth stance (§2.4.2):
 * it tightens every guard's effective detection range. Hidden is the "never generates a sighting"
 * escape hatch used for downed/dead/teleporting actors so they cannot spuriously confirm.
 */
UENUM(BlueprintType)
enum class EGSStealthStance : uint8
{
	Standing = 0,
	Crouched,
	Hidden
};

/**
 * Per-observer detection tuning. One readable rule (§2.4): range scales with stance and cover,
 * and a sighting must hold ConfirmHoldSeconds to become a signal. Everything else is trim.
 */
USTRUCT(BlueprintType)
struct GOBLINSIEGE_API FGSDetectionTuning
{
	GENERATED_BODY()

	/** Range at which a standing, fully exposed goblin can be seen at all, in cm. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Detection", meta = (ClampMin = "0.0"))
	float BaseSightRange = 2400.f;

	/** Multiplier applied to BaseSightRange while the target is crouched (§2.4.2). */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Detection", meta = (ClampMin = "0.0", ClampMax = "1.0"))
	float CrouchRangeMultiplier = 0.55f;

	/** Multiplier applied when only a sliver of the target clears the cover geometry. Exposure of
	 *  1.0 lerps this back to 1.0 - hedgerows, fences and haycarts are the hamlet's cover language. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Detection", meta = (ClampMin = "0.0", ClampMax = "1.0"))
	float FullCoverRangeMultiplier = 0.3f;

	/** Half-angle of the guard's vision cone, degrees from the (possibly drooping) view direction. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Detection", meta = (ClampMin = "1.0", ClampMax = "179.0"))
	float PeripheralHalfAngleDegrees = 60.f;

	/** THE rule: hold the sighting this long to confirm. Break line of sight first and it cost
	 *  the player nothing - the timer resets to zero, it is not a partial signal. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Detection", meta = (ClampMin = "0.05"))
	float ConfirmHoldSeconds = 1.5f;

	/** Unbroken seconds out of sight after which a confirmed target is forgotten and could be
	 *  confirmed (and re-signalled) again. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Detection", meta = (ClampMin = "0.0"))
	float ForgetSeconds = 4.f;

	/** Fraction of body sample points that must clear cover before the guard sees anything at all. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Detection", meta = (ClampMin = "0.0", ClampMax = "1.0"))
	float MinimumExposureToSee = 0.05f;

	float GetStanceRangeMultiplier(EGSStealthStance Stance) const
	{
		switch (Stance)
		{
		case EGSStealthStance::Crouched:	return FMath::Max(0.f, CrouchRangeMultiplier);
		case EGSStealthStance::Hidden:		return 0.f;
		default:							return 1.f;
		}
	}

	/** Stance x cover x doze, folded into the one number the range test uses. */
	float GetEffectiveRange(EGSStealthStance Stance, float Exposure01, float DozeRangeMultiplier) const
	{
		const float CoverMultiplier = FMath::Lerp(FMath::Clamp(FullCoverRangeMultiplier, 0.f, 1.f), 1.f, FMath::Clamp(Exposure01, 0.f, 1.f));
		return FMath::Max(0.f, BaseSightRange) * GetStanceRangeMultiplier(Stance) * CoverMultiplier * FMath::Max(0.f, DozeRangeMultiplier);
	}
};

/**
 * The watchman's doze (§2.4): a guard who has seen nothing for a while lets his vision cone sag
 * toward his boots. Purely an observer-side modifier - it shortens range, narrows the cone and
 * pitches the look direction down, and any sighting or noise snaps it back to zero.
 */
USTRUCT(BlueprintType)
struct GOBLINSIEGE_API FGSDozeTuning
{
	GENERATED_BODY()

	/** Watchmen doze; roving patrols can turn it off. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Doze")
	bool bCanDoze = true;

	/** Quiet seconds before the droop starts. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Doze", meta = (ClampMin = "0.0"))
	float DrowseStartSeconds = 10.f;

	/** Quiet seconds at which the droop is at its worst. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Doze", meta = (ClampMin = "0.1"))
	float FullDozeSeconds = 26.f;

	/** How far down the cone pitches at full doze, degrees. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Doze", meta = (ClampMin = "0.0", ClampMax = "85.0"))
	float MaxDroopDegrees = 38.f;

	/** Range multiplier at full doze. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Doze", meta = (ClampMin = "0.0", ClampMax = "1.0"))
	float DozeRangeMultiplier = 0.45f;

	/** Cone half-angle multiplier at full doze. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Doze", meta = (ClampMin = "0.05", ClampMax = "1.0"))
	float DozeConeMultiplier = 0.6f;

	float GetDozeAlpha(float DozeSeconds) const
	{
		if (!bCanDoze)
		{
			return 0.f;
		}
		const float Span = FMath::Max(0.01f, FullDozeSeconds - DrowseStartSeconds);
		return FMath::Clamp((DozeSeconds - DrowseStartSeconds) / Span, 0.f, 1.f);
	}
};

/** One observer's running book on one target. Lives only on the server. */
USTRUCT(BlueprintType)
struct GOBLINSIEGE_API FGSSightingRecord
{
	GENERATED_BODY()

	/** Seconds of unbroken sight accumulated toward ConfirmHoldSeconds. Reset to 0 the instant
	 *  line of sight breaks - duck behind the haycart and you were never there. */
	UPROPERTY(BlueprintReadOnly, Category = "Sighting")
	float ConfirmTimer = 0.f;

	/** Seconds since this observer last had the target in sight. */
	UPROPERTY(BlueprintReadOnly, Category = "Sighting")
	float TimeSinceLastSeen = 0.f;

	/** True once the hold landed. Latches so a single confirm emits a single soft signal. */
	UPROPERTY(BlueprintReadOnly, Category = "Sighting")
	bool bConfirmed = false;

	/** True if the target cleared cover, range and cone on the most recent evaluation. */
	UPROPERTY(BlueprintReadOnly, Category = "Sighting")
	bool bVisibleNow = false;

	/** Fraction of body sample points that cleared cover geometry last evaluation. */
	UPROPERTY(BlueprintReadOnly, Category = "Sighting")
	float LastExposure01 = 0.f;

	/** Where the target was when last seen - the investigate point for the noise/search pass. */
	UPROPERTY(BlueprintReadOnly, Category = "Sighting")
	FVector LastKnownLocation = FVector::ZeroVector;
};

// The one funnel between "a guard confirmed a goblin" and the rest of the game (design doc §2.4,
// §2.6): it de-duplicates confirms into exactly one soft signal, hands that signal to
// AGSGameState::ReportConfirmedSighting() so the town moves to Suspicious, and remembers whether
// anyone confirmed a goblin before the first objective caught fire ("First Spark Unseen", §2.4).
// 2026-08-04 (Block D): also owns the stealth-target registry and stance resolution so the
// perception component never has to sweep the world.
#pragma once

#include "CoreMinimal.h"
#include "Subsystems/WorldSubsystem.h"
#include "Stealth/GSStealthTypes.h"
#include "GSStealthSubsystem.generated.h"

DECLARE_DYNAMIC_MULTICAST_DELEGATE_ThreeParams(FGSOnStealthConfirmSignal, AActor*, Observer, AActor*, Target, int32, TotalConfirms);
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FGSOnFirstSparkResolved, bool, bUnseen);

/** Non-reflected key: which observer confirmed which target. Weak so it never keeps actors alive. */
struct FGSConfirmKey
{
	TWeakObjectPtr<const AActor> Observer;
	TWeakObjectPtr<const AActor> Target;

	bool operator==(const FGSConfirmKey& Other) const
	{
		return Observer == Other.Observer && Target == Other.Target;
	}

	friend uint32 GetTypeHash(const FGSConfirmKey& Key)
	{
		return HashCombine(GetTypeHash(Key.Observer), GetTypeHash(Key.Target));
	}
};

UCLASS()
class GOBLINSIEGE_API UGSStealthSubsystem : public UWorldSubsystem
{
	GENERATED_BODY()

public:
	virtual void Deinitialize() override;

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth", meta = (WorldContext = "WorldContextObject"))
	static UGSStealthSubsystem* Get(const UObject* WorldContextObject);

	// ---------------------------------------------------------------- target registry

	/** Anything a guard should be able to confirm. Player pawns are picked up automatically;
	 *  AI goblins and other sneaking actors register here. */
	UFUNCTION(BlueprintCallable, Category = "GoblinSiege|Stealth")
	void RegisterStealthTarget(AActor* Target);

	UFUNCTION(BlueprintCallable, Category = "GoblinSiege|Stealth")
	void UnregisterStealthTarget(AActor* Target);

	/** Fills Out with every live stealth target: explicit registrations plus every player pawn. */
	void GatherStealthTargets(TArray<AActor*>& OutTargets) const;

	// ---------------------------------------------------------------- stance

	/** Crouch comes straight off ACharacter unless something set an explicit override. */
	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	EGSStealthStance GetStanceFor(const AActor* Target) const;

	/** Force a stance - used for downed/dead actors (Hidden) and for AI that fakes a crouch. */
	UFUNCTION(BlueprintCallable, Category = "GoblinSiege|Stealth")
	void SetStanceOverride(AActor* Target, EGSStealthStance Stance);

	UFUNCTION(BlueprintCallable, Category = "GoblinSiege|Stealth")
	void ClearStanceOverride(AActor* Target);

	// ---------------------------------------------------------------- confirms

	/**
	 * Server-side. A guard's 1.5s hold landed. Emits exactly one soft signal into the alarm
	 * system (AGSGameState::ReportConfirmedSighting -> Quiet becomes Suspicious) and counts the
	 * confirm for First Spark Unseen. Repeat calls for the same observer/target pair inside
	 * ConfirmDedupeSeconds are swallowed. Returns true if a signal was actually emitted.
	 */
	UFUNCTION(BlueprintCallable, Category = "GoblinSiege|Stealth")
	bool ReportSightingConfirmed(AActor* Observer, AActor* Target);

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	int32 GetConfirmedSightingCount() const { return ConfirmedSightingCount; }

	// ---------------------------------------------------------------- first spark unseen

	/** Server-side. Call the moment the first objective/structure ignites. Idempotent: the first
	 *  call snapshots whether any goblin had been confirmed up to that point. */
	UFUNCTION(BlueprintCallable, Category = "GoblinSiege|Stealth")
	void NotifyFirstObjectiveIgnited();

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	bool HasFirstSparkHappened() const { return bFirstSparkHappened; }

	/** Before the first fire: is the bonus still live? After it: did it pay out? */
	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	bool IsFirstSparkUnseen() const { return bFirstSparkHappened ? bFirstSparkUnseen : (ConfirmedSightingCount == 0); }

	/** Broadcast once per emitted soft signal. */
	UPROPERTY(BlueprintAssignable, Category = "GoblinSiege|Stealth")
	FGSOnStealthConfirmSignal OnStealthConfirmSignal;

	/** Broadcast once, when the first objective ignites, with the bonus verdict. */
	UPROPERTY(BlueprintAssignable, Category = "GoblinSiege|Stealth")
	FGSOnFirstSparkResolved OnFirstSparkResolved;

	/** Window in which a repeat confirm from the same observer on the same target is silent. */
	UPROPERTY(EditDefaultsOnly, Category = "GoblinSiege|Stealth", meta = (ClampMin = "0.0"))
	float ConfirmDedupeSeconds = 8.f;

private:
	/** Weak so unregistering is optional - dead actors fall out on the next gather. */
	TSet<TWeakObjectPtr<AActor>> RegisteredTargets;

	TMap<TWeakObjectPtr<const AActor>, EGSStealthStance> StanceOverrides;

	TMap<FGSConfirmKey, double> LastConfirmTimes;

	int32 ConfirmedSightingCount = 0;

	bool bFirstSparkHappened = false;

	bool bFirstSparkUnseen = false;
};

// Implements the confirm funnel described in design doc §2.4 / §2.6: one confirm, one soft
// signal, town to Suspicious - and the First Spark Unseen ledger.

#include "Stealth/GSStealthSubsystem.h"

#include "Core/GSGameState.h"
#include "Engine/Engine.h"
#include "Engine/World.h"
#include "GameFramework/Character.h"
#include "GameFramework/CharacterMovementComponent.h"
#include "GameFramework/Pawn.h"
#include "GameFramework/PlayerController.h"

void UGSStealthSubsystem::Deinitialize()
{
	RegisteredTargets.Reset();
	StanceOverrides.Reset();
	LastConfirmTimes.Reset();
	ConfirmedSightingCount = 0;
	bFirstSparkHappened = false;
	bFirstSparkUnseen = false;

	Super::Deinitialize();
}

UGSStealthSubsystem* UGSStealthSubsystem::Get(const UObject* WorldContextObject)
{
	if (!GEngine || !WorldContextObject)
	{
		return nullptr;
	}

	if (const UWorld* World = GEngine->GetWorldFromContextObject(WorldContextObject, EGetWorldErrorMode::ReturnNull))
	{
		return World->GetSubsystem<UGSStealthSubsystem>();
	}

	return nullptr;
}

void UGSStealthSubsystem::RegisterStealthTarget(AActor* Target)
{
	if (IsValid(Target))
	{
		RegisteredTargets.Add(Target);
	}
}

void UGSStealthSubsystem::UnregisterStealthTarget(AActor* Target)
{
	if (Target)
	{
		RegisteredTargets.Remove(Target);
		StanceOverrides.Remove(Target);
	}
}

void UGSStealthSubsystem::GatherStealthTargets(TArray<AActor*>& OutTargets) const
{
	OutTargets.Reset();

	for (const TWeakObjectPtr<AActor>& WeakTarget : RegisteredTargets)
	{
		if (AActor* Target = WeakTarget.Get())
		{
			if (IsValid(Target))
			{
				OutTargets.AddUnique(Target);
			}
		}
	}

	// Player pawns are always fair game - no one has to remember to register the goblins.
	if (const UWorld* World = GetWorld())
	{
		for (FConstPlayerControllerIterator It = World->GetPlayerControllerIterator(); It; ++It)
		{
			if (const APlayerController* PC = It->Get())
			{
				if (APawn* Pawn = PC->GetPawn())
				{
					if (IsValid(Pawn))
					{
						OutTargets.AddUnique(Pawn);
					}
				}
			}
		}
	}
}

EGSStealthStance UGSStealthSubsystem::GetStanceFor(const AActor* Target) const
{
	if (!IsValid(Target))
	{
		return EGSStealthStance::Hidden;
	}

	if (const EGSStealthStance* Override = StanceOverrides.Find(Target))
	{
		return *Override;
	}

	if (const ACharacter* Character = Cast<ACharacter>(Target))
	{
		if (Character->bIsCrouched)
		{
			return EGSStealthStance::Crouched;
		}

		if (const UCharacterMovementComponent* Movement = Character->GetCharacterMovement())
		{
			if (Movement->IsCrouching())
			{
				return EGSStealthStance::Crouched;
			}
		}
	}

	return EGSStealthStance::Standing;
}

void UGSStealthSubsystem::SetStanceOverride(AActor* Target, EGSStealthStance Stance)
{
	if (IsValid(Target))
	{
		StanceOverrides.Add(Target, Stance);
	}
}

void UGSStealthSubsystem::ClearStanceOverride(AActor* Target)
{
	if (Target)
	{
		StanceOverrides.Remove(Target);
	}
}

bool UGSStealthSubsystem::ReportSightingConfirmed(AActor* Observer, AActor* Target)
{
	UWorld* World = GetWorld();
	if (!World || !IsValid(Observer) || !IsValid(Target))
	{
		return false;
	}

	// Signals are authored on the server only; clients never move the town's state of mind.
	if (World->GetNetMode() == NM_Client)
	{
		return false;
	}

	const double Now = World->GetTimeSeconds();

	FGSConfirmKey Key;
	Key.Observer = Observer;
	Key.Target = Target;

	if (const double* LastTime = LastConfirmTimes.Find(Key))
	{
		if (Now - *LastTime < static_cast<double>(FMath::Max(0.f, ConfirmDedupeSeconds)))
		{
			return false;
		}
	}

	LastConfirmTimes.Add(Key, Now);
	++ConfirmedSightingCount;

	// Exactly one uncorroborated soft signal: Quiet -> Suspicious, and it takes a second signal
	// to escalate past that (design doc §2.4, §2.6).
	if (AGSGameState* GameState = World->GetGameState<AGSGameState>())
	{
		GameState->ReportConfirmedSighting();
	}

	OnStealthConfirmSignal.Broadcast(Observer, Target, ConfirmedSightingCount);
	return true;
}

void UGSStealthSubsystem::NotifyFirstObjectiveIgnited()
{
	if (bFirstSparkHappened)
	{
		return;
	}

	bFirstSparkHappened = true;
	bFirstSparkUnseen = (ConfirmedSightingCount == 0);

	OnFirstSparkResolved.Broadcast(bFirstSparkUnseen);
}

// A guard's eyes (design doc §2.4): per-target confirm timers that reset the instant line of
// sight breaks, detection range scaled by the target's crouch stance and by how much of them
// clears cover geometry, and a watchman vision cone that visibly droops on a doze timer.
// Server-authoritative - the confirm that lands here is the one soft signal the town hears.
// 2026-08-04 (Block D): first perception code in the module.
#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "Stealth/GSStealthTypes.h"
#include "GSSightPerceptionComponent.generated.h"

DECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FGSOnSightingConfirmed, AActor*, Observer, AActor*, Target);

/**
 * Drop on any human who is supposed to be able to spot a goblin. Ticks on the server only.
 * Watchmen leave bCanDoze on; roving patrols turn it off in their archetype defaults.
 */
UCLASS(ClassGroup = (GoblinSiege), meta = (BlueprintSpawnableComponent))
class GOBLINSIEGE_API UGSSightPerceptionComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	UGSSightPerceptionComponent();

	virtual void BeginPlay() override;
	virtual void TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction) override;

	// ---------------------------------------------------------------- queries

	/** Copy of this observer's book on Target - default-constructed if it has no book. */
	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	FGSSightingRecord GetSightingRecord(AActor* Target) const;

	/** 0..1 progress toward the 1.5s hold for a specific target. */
	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	float GetConfirmProgress01(AActor* Target) const;

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	bool HasConfirmedSighting(AActor* Target) const;

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	bool HasAnyConfirmedSighting() const;

	/** Where this guard is actually looking, droop included. Aim the cone art at this. */
	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	FVector GetVisionDirection() const;

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	FVector GetEyeLocation() const;

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	float GetDozeAlpha() const { return DozeTuning.GetDozeAlpha(DozeSeconds); }

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	float GetCurrentDroopDegrees() const { return DozeTuning.MaxDroopDegrees * GetDozeAlpha(); }

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	float GetEffectiveHalfAngleDegrees() const;

	UFUNCTION(BlueprintPure, Category = "GoblinSiege|Stealth")
	float GetDozeRangeMultiplier() const;

	// ---------------------------------------------------------------- commands

	/** Snap the guard awake - call from noise, damage, corpse sightings, coin tosses. */
	UFUNCTION(BlueprintCallable, Category = "GoblinSiege|Stealth")
	void Rouse();

	/** Wipe every book. Used on unaware-state resets and takedown cleanup. */
	UFUNCTION(BlueprintCallable, Category = "GoblinSiege|Stealth")
	void ForgetAll();

	/** Fired on the server the frame a hold completes, before the subsystem signal goes out. */
	UPROPERTY(BlueprintAssignable, Category = "GoblinSiege|Stealth")
	FGSOnSightingConfirmed OnSightingConfirmed;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "GoblinSiege|Stealth")
	FGSDetectionTuning Tuning;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "GoblinSiege|Stealth")
	FGSDozeTuning DozeTuning;

	/** Draws the (drooping) cone and the confirm state. Cheap enough to leave on in PIE. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "GoblinSiege|Stealth")
	bool bDrawDebugVisionCone = false;

protected:
	/** Cone + range + cover test. OutExposure01 is the fraction of body samples clearing cover. */
	bool EvaluateVisibility(AActor* Target, float& OutExposure01) const;

	void ConfirmSighting(AActor* Target, FGSSightingRecord& Record);

	void UpdateDoze(float DeltaTime, bool bSawSomeone);

	void DrawDebugVision(float DeltaTime) const;

private:
	/** Weak keys: a target that dies or streams out just drops off the books. Not reflected, so
	 *  no UPROPERTY - weak pointers keep nothing alive. */
	TMap<TWeakObjectPtr<AActor>, FGSSightingRecord> Sightings;

	float DozeSeconds = 0.f;
};

// Implements design doc §2.4's one readable rule: hold the sighting ~1.5 seconds to confirm,
// break line of sight and the timer is zero again - not a partial signal, no signal at all.

#include "Stealth/GSSightPerceptionComponent.h"

#include "Alarm/GSAlarmTypes.h"
#include "Core/GSGameState.h"
#include "DrawDebugHelpers.h"
#include "Engine/World.h"
#include "GameFramework/Actor.h"
#include "Stealth/GSStealthSubsystem.h"

UGSSightPerceptionComponent::UGSSightPerceptionComponent()
{
	PrimaryComponentTick.bCanEverTick = true;
	PrimaryComponentTick.bStartWithTickEnabled = true;
	// 20Hz is plenty for a 1.5s hold and keeps the line traces off the frame budget.
	PrimaryComponentTick.TickInterval = 0.05f;

	SetIsReplicatedByDefault(false);
}

void UGSSightPerceptionComponent::BeginPlay()
{
	Super::BeginPlay();

	const AActor* Owner = GetOwner();
	if (!Owner || !Owner->HasAuthority())
	{
		// Detection is a server-side truth. Clients keep the component for its accessors only.
		SetComponentTickEnabled(false);
	}
}

void UGSSightPerceptionComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

	AActor* Observer = GetOwner();
	if (!IsValid(Observer) || !Observer->HasAuthority())
	{
		return;
	}

	TArray<AActor*> Targets;
	if (UGSStealthSubsystem* Stealth = UGSStealthSubsystem::Get(this))
	{
		Stealth->GatherStealthTargets(Targets);
	}

	TSet<AActor*> Processed;
	Processed.Reserve(Targets.Num());

	bool bSawSomeone = false;

	for (AActor* Target : Targets)
	{
		if (!IsValid(Target) || Target == Observer)
		{
			continue;
		}

		Processed.Add(Target);

		float Exposure01 = 0.f;
		const bool bVisible = EvaluateVisibility(Target, Exposure01);

		FGSSightingRecord& Record = Sightings.FindOrAdd(Target);
		Record.bVisibleNow = bVisible;
		Record.LastExposure01 = Exposure01;

		if (bVisible)
		{
			bSawSomeone = true;
			Record.TimeSinceLastSeen = 0.f;
			Record.LastKnownLocation = Target->GetActorLocation();

			if (!Record.bConfirmed)
			{
				Record.ConfirmTimer += DeltaTime;
				if (Record.ConfirmTimer >= Tuning.ConfirmHoldSeconds)
				{
					ConfirmSighting(Target, Record);
				}
			}
		}
		else
		{
			// Duck behind the haycart before the confirm lands and you were never there.
			Record.ConfirmTimer = 0.f;
			Record.TimeSinceLastSeen += DeltaTime;

			if (Record.TimeSinceLastSeen >= Tuning.ForgetSeconds)
			{
				Sightings.Remove(Target);
			}
		}
	}

	// Age out anything the registry stopped reporting (dead, streamed out, unregistered).
	for (TMap<TWeakObjectPtr<AActor>, FGSSightingRecord>::TIterator It(Sightings); It; ++It)
	{
		AActor* Key = It.Key().Get();
		if (!IsValid(Key))
		{
			It.RemoveCurrent();
			continue;
		}

		if (Processed.Contains(Key))
		{
			continue;
		}

		FGSSightingRecord& Record = It.Value();
		Record.bVisibleNow = false;
		Record.ConfirmTimer = 0.f;
		Record.TimeSinceLastSeen += DeltaTime;
		if (Record.TimeSinceLastSeen >= Tuning.ForgetSeconds)
		{
			It.RemoveCurrent();
		}
	}

	UpdateDoze(DeltaTime, bSawSomeone);
	DrawDebugVision(DeltaTime);
}

bool UGSSightPerceptionComponent::EvaluateVisibility(AActor* Target, float& OutExposure01) const
{
	OutExposure01 = 0.f;

	const AActor* Observer = GetOwner();
	UWorld* World = GetWorld();
	if (!IsValid(Target) || !IsValid(Observer) || !World)
	{
		return false;
	}

	EGSStealthStance Stance = EGSStealthStance::Standing;
	if (UGSStealthSubsystem* Stealth = UGSStealthSubsystem::Get(this))
	{
		Stance = Stealth->GetStanceFor(Target);
	}

	if (Stance == EGSStealthStance::Hidden)
	{
		return false;
	}

	const FVector EyeLocation = GetEyeLocation();
	const FVector TargetCenter = Target->GetActorLocation();
	const float Distance = FVector::Dist(EyeLocation, TargetCenter);

	if (Distance <= 1.f)
	{
		OutExposure01 = 1.f;
		return true;
	}

	// Cheap reject before any traces: nothing can ever be seen past the base range.
	if (Distance > Tuning.BaseSightRange)
	{
		return false;
	}

	const FVector ToTarget = (TargetCenter - EyeLocation).GetSafeNormal();
	const FVector ViewDirection = GetVisionDirection();
	const float CosLimit = FMath::Cos(FMath::DegreesToRadians(FMath::Clamp(GetEffectiveHalfAngleDegrees(), 1.f, 179.f)));
	if (FVector::DotProduct(ViewDirection, ToTarget) < CosLimit)
	{
		return false;
	}

	// Cover geometry: sample the silhouette rather than one hero ray, so a hedgerow that clips
	// the legs shortens the guard's range instead of doing nothing at all.
	const float HalfHeight = FMath::Max(20.f, Target->GetSimpleCollisionHalfHeight());
	const float Radius = FMath::Max(10.f, Target->GetSimpleCollisionRadius() * 0.8f);
	const FVector RightOffset = FVector::CrossProduct(FVector::UpVector, ToTarget).GetSafeNormal() * Radius;

	TArray<FVector, TInlineAllocator<5>> Samples;
	Samples.Add(TargetCenter + FVector(0.f, 0.f, HalfHeight * 0.85f));
	Samples.Add(TargetCenter);
	Samples.Add(TargetCenter - FVector(0.f, 0.f, HalfHeight * 0.6f));
	Samples.Add(TargetCenter + RightOffset);
	Samples.Add(TargetCenter - RightOffset);

	FCollisionQueryParams Params(TEXT("GSSightConfirm"), /*bTraceComplex=*/false, Observer);
	Params.AddIgnoredActor(Target);

	int32 VisibleSamples = 0;
	for (const FVector& Sample : Samples)
	{
		if (!World->LineTraceTestByChannel(EyeLocation, Sample, ECC_Visibility, Params))
		{
			++VisibleSamples;
		}
	}

	OutExposure01 = Samples.Num() > 0 ? static_cast<float>(VisibleSamples) / static_cast<float>(Samples.Num()) : 0.f;
	if (OutExposure01 <= Tuning.MinimumExposureToSee)
	{
		OutExposure01 = 0.f;
		return false;
	}

	const float EffectiveRange = Tuning.GetEffectiveRange(Stance, OutExposure01, GetDozeRangeMultiplier());
	return Distance <= EffectiveRange;
}

void UGSSightPerceptionComponent::ConfirmSighting(AActor* Target, FGSSightingRecord& Record)
{
	Record.bConfirmed = true;
	Record.ConfirmTimer = Tuning.ConfirmHoldSeconds;
	DozeSeconds = 0.f;

	OnSightingConfirmed.Broadcast(GetOwner(), Target);

	if (UGSStealthSubsystem* Stealth = UGSStealthSubsystem::Get(this))
	{
		// Exactly one soft signal per confirm - the subsystem owns the de-duplication.
		Stealth->ReportSightingConfirmed(GetOwner(), Target);
	}
}

void UGSSightPerceptionComponent::UpdateDoze(float DeltaTime, bool bSawSomeone)
{
	if (!DozeTuning.bCanDoze || bSawSomeone)
	{
		DozeSeconds = 0.f;
		return;
	}

	const UWorld* World = GetWorld();
	const AGSGameState* GameState = World ? World->GetGameState<AGSGameState>() : nullptr;
	if (GameState && GameState->GetAlarmPhase() >= EGSAlarmPhase::Raid)
	{
		// Nobody dozes once the bell has rung.
		DozeSeconds = 0.f;
		return;
	}

	DozeSeconds += DeltaTime;
}

void UGSSightPerceptionComponent::DrawDebugVision(float DeltaTime) const
{
#if ENABLE_DRAW_DEBUG
	if (!bDrawDebugVisionCone)
	{
		return;
	}

	UWorld* World = GetWorld();
	if (!World)
	{
		return;
	}

	bool bAnyConfirmed = false;
	bool bAnyHolding = false;
	for (const TPair<TWeakObjectPtr<AActor>, FGSSightingRecord>& Pair : Sightings)
	{
		bAnyConfirmed |= Pair.Value.bConfirmed;
		bAnyHolding |= (!Pair.Value.bConfirmed && Pair.Value.ConfirmTimer > 0.f);
	}

	FColor ConeColor = FColor::Green;
	if (bAnyConfirmed)
	{
		ConeColor = FColor::Red;
	}
	else if (bAnyHolding)
	{
		ConeColor = FColor::Orange;
	}
	else if (GetDozeAlpha() > 0.f)
	{
		ConeColor = FColor::Blue;
	}

	const float Length = FMath::Max(50.f, Tuning.BaseSightRange * GetDozeRangeMultiplier());
	const float AngleRadians = FMath::DegreesToRadians(FMath::Clamp(GetEffectiveHalfAngleDegrees(), 1.f, 89.f));
	const float Lifetime = FMath::Max(DeltaTime, 0.05f) * 1.05f;

	DrawDebugCone(World, GetEyeLocation(), GetVisionDirection(), Length, AngleRadians, AngleRadians, 16, ConeColor, false, Lifetime, 0, 1.f);

	for (const TPair<TWeakObjectPtr<AActor>, FGSSightingRecord>& Pair : Sightings)
	{
		const AActor* Target = Pair.Key.Get();
		if (!IsValid(Target) || Pair.Value.ConfirmTimer <= 0.f)
		{
			continue;
		}

		const float Progress = FMath::Clamp(Pair.Value.ConfirmTimer / FMath::Max(0.05f, Tuning.ConfirmHoldSeconds), 0.f, 1.f);
		DrawDebugLine(World, GetEyeLocation(), Target->GetActorLocation(), Pair.Value.bConfirmed ? FColor::Red : FColor::Yellow, false, Lifetime, 0, 1.f + 2.f * Progress);
	}
#endif
}

FGSSightingRecord UGSSightPerceptionComponent::GetSightingRecord(AActor* Target) const
{
	if (Target)
	{
		if (const FGSSightingRecord* Found = Sightings.Find(Target))
		{
			return *Found;
		}
	}

	return FGSSightingRecord();
}

float UGSSightPerceptionComponent::GetConfirmProgress01(AActor* Target) const
{
	if (Target)
	{
		if (const FGSSightingRecord* Found = Sightings.Find(Target))
		{
			return FMath::Clamp(Found->ConfirmTimer / FMath::Max(0.05f, Tuning.ConfirmHoldSeconds), 0.f, 1.f);
		}
	}

	return 0.f;
}

bool UGSSightPerceptionComponent::HasConfirmedSighting(AActor* Target) const
{
	if (Target)
	{
		if (const FGSSightingRecord* Found = Sightings.Find(Target))
		{
			return Found->bConfirmed;
		}
	}

	return false;
}

bool UGSSightPerceptionComponent::HasAnyConfirmedSighting() const
{
	for (const TPair<TWeakObjectPtr<AActor>, FGSSightingRecord>& Pair : Sightings)
	{
		if (Pair.Value.bConfirmed)
		{
			return true;
		}
	}

	return false;
}

FVector UGSSightPerceptionComponent::GetEyeLocation() const
{
	const AActor* Observer = GetOwner();
	if (!IsValid(Observer))
	{
		return FVector::ZeroVector;
	}

	FVector EyeLocation = FVector::ZeroVector;
	FRotator EyeRotation = FRotator::ZeroRotator;
	Observer->GetActorEyesViewPoint(EyeLocation, EyeRotation);
	return EyeLocation;
}

FVector UGSSightPerceptionComponent::GetVisionDirection() const
{
	const AActor* Observer = GetOwner();
	if (!IsValid(Observer))
	{
		return FVector::ForwardVector;
	}

	FVector EyeLocation = FVector::ZeroVector;
	FRotator EyeRotation = FRotator::ZeroRotator;
	Observer->GetActorEyesViewPoint(EyeLocation, EyeRotation);

	// The droop: a dozing watchman's cone sags toward his boots.
	EyeRotation.Pitch = FMath::Clamp(EyeRotation.Pitch - GetCurrentDroopDegrees(), -89.f, 89.f);
	return EyeRotation.Vector();
}

float UGSSightPerceptionComponent::GetEffectiveHalfAngleDegrees() const
{
	return Tuning.PeripheralHalfAngleDegrees * FMath::Lerp(1.f, FMath::Clamp(DozeTuning.DozeConeMultiplier, 0.05f, 1.f), GetDozeAlpha());
}

float UGSSightPerceptionComponent::GetDozeRangeMultiplier() const
{
	return FMath::Lerp(1.f, FMath::Clamp(DozeTuning.DozeRangeMultiplier, 0.f, 1.f), GetDozeAlpha());
}

void UGSSightPerceptionComponent::Rouse()
{
	DozeSeconds = 0.f;
}

void UGSSightPerceptionComponent::ForgetAll()
{
	Sightings.Reset();
}
